    def findTargetSumWays(self, nums: List[int], target: int) -> int:
        total = sum(nums)
        if total + target < 0 or (total + target) % 2:
            return 0
        bag = (total + target) // 2
        dp = [0] * (bag + 1)
        dp[0] = 1
        for x in nums:
            for j in range(bag, x - 1, -1):
                dp[j] += dp[j - x]
        return dp[bag]

